/**
 * Batch 8 — ~110 verified India Quiz questions.
 * 10 per category × 11 categories.
 */
import { db } from '@/lib/db';
import { checkDuplicate } from '@/lib/quiz/duplicate-detector';

interface Q {
  slug: string; categoryId: string; text: string;
  options: [string, string, string, string]; correctIndex: number;
  explanation: string; source: string; difficulty: 'easy'|'medium'|'hard';
}

const BATCH: Q[] = [
  // ═══ cat-gk (10) ═══
  { slug: 'gk-india-first-3d-printed-post-office', categoryId: 'cat-gk', text: 'India\'s first 3D-printed post office was inaugurated in which city in 2023?', options: ['Mumbai', 'Bengaluru', 'Delhi', 'Chennai'], correctIndex: 1, explanation: 'India\'s first 3D-printed post office was inaugurated on 18 August 2023 in Bengaluru (Cambridge Layout). It was built by Larsen & Toubro (L&T) using 3D concrete printing technology in 43 days, reducing construction time and material waste significantly compared to traditional methods.', source: 'Department of Posts / Ministry of Communications', difficulty: 'medium' },
  { slug: 'gk-india-chandrayaan-3-pragyan-rover', categoryId: 'cat-gk', text: 'The Pragyan rover from Chandrayaan-3 was designed to conduct what type of experiments on the Moon?', options: ['Atmospheric sampling', 'In-situ measurements of lunar surface composition using X-ray and laser spectroscopy', 'Seismology only', 'Gravity mapping only'], correctIndex: 1, explanation: 'The Pragyan rover carried two instruments: APXS (Alpha Particle X-ray Spectrometer) to determine the elemental composition of the lunar surface, and LIBS (Laser Induced Breakdown Spectroscope) to measure chemical and mineralogical composition. It confirmed the presence of sulphur, iron, oxygen, and other elements near the lunar south pole.', source: 'ISRO official website / Chandrayaan-3 mission report', difficulty: 'medium' },
  { slug: 'gk-india-longest-rail-tunnel-pir-panjal', categoryId: 'cat-gk', text: 'The Pir Panjal Railway Tunnel, the longest railway tunnel in India, is located in which state/UT?', options: ['Himachal Pradesh', 'Jammu & Kashmir', 'Uttarakhand', 'Ladakh'], correctIndex: 1, explanation: 'The Pir Panjal Railway Tunnel (also called Banihal-Qazigund tunnel) is 11.2 km long and is located in Jammu & Kashmir. It is part of the Udhampur-Srinagar-Baramulla rail link project. It reduces the distance between Banihal and Qazigund and enables year-round rail connectivity to the Kashmir Valley.', source: 'Indian Railways / Ministry of Railways', difficulty: 'medium' },
  { slug: 'gk-india-national-space-day-date', categoryId: 'cat-gk', text: 'India celebrated its first National Space Day on which date?', options: ['15 August 2024', '23 August 2024', '2 October 2024', '26 November 2024'], correctIndex: 1, explanation: 'India celebrated its first National Space Day on 23 August 2024, marking the first anniversary of Chandrayaan-3\'s successful Moon landing on 23 August 2023. The government designated 23 August as National Space Day to commemorate India becoming the first country to land near the lunar south pole.', source: 'ISRO / Department of Space, Government of India', difficulty: 'easy' },
  { slug: 'gk-india-largest-nuclear-plant', categoryId: 'cat-gk', text: 'Which is the largest nuclear power plant in India by installed capacity?', options: ['Tarapur Atomic Power Station (Maharashtra)', 'Kudankulam Nuclear Power Plant (Tamil Nadu)', 'Rajasthan Atomic Power Station', 'Kaiga Generating Station (Karnataka)'], correctIndex: 1, explanation: 'Kudankulam Nuclear Power Plant (KKNPP) in Tamil Nadu is India\'s largest nuclear power plant. It has 2 operational VVER-1000 reactors (Unit 1 and 2, 1,000 MW each = 2,000 MW total). Four more reactors (Units 3-6) are under construction, which will make KKNPP one of the world\'s largest nuclear plants (6,000 MW total when complete).', source: 'Nuclear Power Corporation of India Limited (NPCIL) / Department of Atomic Energy', difficulty: 'medium' },
  { slug: 'gk-india-biggest-telescope-meter', categoryId: 'cat-gk', text: 'The Giant Metrewave Radio Telescope (GMRT), one of the world\'s largest radio telescopes, is located near which city?', options: ['Bengaluru', 'Pune (Khodad, Maharashtra)', 'Hyderabad', 'Ooty'], correctIndex: 1, explanation: 'The Giant Metrewave Radio Telescope (GMRT) is located at Khodad, near Pune, Maharashtra. Operated by NCRA (National Centre for Radio Astrophysics), it consists of 30 dish antennas of 45 m diameter each, spread over 25 km. It was upgraded in 2019 (uGMRT). GMRT is used to study pulsars, galaxies, and the early universe at low radio frequencies.', source: 'National Centre for Radio Astrophysics (NCRA) / Tata Institute of Fundamental Research (TIFR)', difficulty: 'hard' },
  { slug: 'gk-india-international-yoga-day-origin', categoryId: 'cat-gk', text: 'The International Day of Yoga was proposed by India at the United Nations and adopted in 2014. It is observed on which date?', options: ['21 June', '2 October', '21 September', '25 December'], correctIndex: 0, explanation: 'The International Day of Yoga is observed on 21 June each year. It was proposed by PM Modi in his UN address on 27 September 2014 and adopted by 177 countries via a record co-sponsorship. The first International Day of Yoga was celebrated on 21 June 2015. The date 21 June was chosen as it is the summer solstice (longest day in the Northern Hemisphere).', source: 'United Nations General Assembly Resolution 69/131 / Ministry of AYUSH', difficulty: 'easy' },
  { slug: 'gk-india-atmanirbhar-bharat-year', categoryId: 'cat-gk', text: 'The "Atmanirbhar Bharat Abhiyan" (Self-Reliant India Campaign) was announced by PM Modi in which year?', options: ['2018', '2020', '2022', '2024'], correctIndex: 1, explanation: 'The "Atmanirbhar Bharat Abhiyan" was announced on 12 May 2020 as part of the COVID-19 economic stimulus package. It had 5 pillars: economy, infrastructure, system, vibrant demography, and demand. The campaign aimed to make India self-reliant by boosting domestic manufacturing, reducing imports, and promoting local brands ("vocal for local").', source: 'Ministry of Finance / PMO India', difficulty: 'medium' },
  { slug: 'gk-india-new-parliament-triang', categoryId: 'cat-gk', text: 'The new Parliament building in India, inaugurated in May 2023, is designed in what shape?', options: ['Circular', 'Triangular', 'Rectangular', 'Hexagonal'], correctIndex: 1, explanation: 'The new Parliament building is triangular in shape, representing the sacred geometry of triangles in Indian culture. It houses a larger Lok Sabha (888 seats, vs 553 in the old building) and Rajya Sabha (384 seats, vs 250). The old Parliament (circular, 1927) was designed by Edwin Lutyens and Herbert Baker.', source: 'Ministry of Housing and Urban Affairs / CPWD', difficulty: 'medium' },
  { slug: 'gk-india-ram-mandir-ayodhya-date', categoryId: 'cat-gk', text: 'The Ram Mandir in Ayodhya was consecrated (pran pratishtha) on which date?', options: ['15 August 2023', '22 January 2024', '26 January 2024', '2 October 2024'], correctIndex: 1, explanation: 'The Ram Mandir in Ayodhya was consecrated (pran pratishtha ceremony) on 22 January 2024. The temple is dedicated to Lord Rama and is built on the site believed to be his birthplace (Ram Janmabhoomi). The Supreme Court\'s 2019 judgment had paved the way for the temple\'s construction. The temple is built in the Nagara style of architecture.', source: 'Shri Ram Janmabhoomi Teerth Kshetra Trust', difficulty: 'easy' },

  // ═══ cat-history (10) ═══
  { slug: 'hist-indus-valley-great-bath-mohenjo', categoryId: 'cat-history', text: 'The Great Bath of Mohenjo-daro is believed to have been used for what purpose?', options: ['Swimming recreation', 'Religious/ritual purification bathing', 'Water storage for drinking', 'Fish farming'], correctIndex: 1, explanation: 'The Great Bath of Mohenjo-daro (12m × 7m, 2.4m deep) is believed to have been used for religious/ritual purification. It was lined with bricks and sealed with bitumen to make it waterproof. A drainage system allowed water to be changed. It is one of the earliest known public water tanks in the world, dating to c. 2500 BCE.', source: 'Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'hist-ashoka-dharma-chakra-24-spokes', categoryId: 'cat-history', text: 'The Ashoka Chakra on India\'s national flag has 24 spokes. In Buddhism, these 24 spokes represent what?', options: ['24 hours of the day', '24 spokes represent the 24 causal laws of dependent origination (Pratityasamutpada)', '24 seasons of the Buddhist calendar', '24 Buddhist councils held'], correctIndex: 1, explanation: 'The 24 spokes of the Ashoka Chakra represent the 24 causal laws of dependent origination (Pratityasamutpada) in Buddhist philosophy — the cycle of cause and effect that leads to suffering and its cessation. The chakra also symbolises the "wheel of law" (dharma chakra) and the continuous motion of justice and progress. It was adopted on the national flag on 22 July 1947.', source: 'Archaeological Survey of India / Government of India national symbols', difficulty: 'hard' },
  { slug: 'hist-delhi-sultanate-alauddin-reforms', categoryId: 'cat-history', text: 'Alauddin Khalji implemented market control reforms. What was his stated primary motivation?', options: ['To reduce inflation', 'To maintain a large standing army at low cost (soldiers\' salaries could be kept low if goods were cheap)', 'To benefit merchants', 'To reduce the power of nobles'], correctIndex: 1, explanation: 'Alauddin Khalji\'s primary motivation for market control was to maintain a large standing army at low cost. By fixing low prices for essential goods, he could pay soldiers low salaries without reducing their purchasing power. He enforced strict price controls through spies (munhiyan) and severe punishments for hoarding and cheating. The reforms were described by Ziauddin Barani in his chronicle.', source: 'Indian Council of Historical Research / Tarikh-i-Firoz Shahi by Ziauddin Barani', difficulty: 'hard' },
  { slug: 'hist-akbar-abolished-jizya-year', categoryId: 'cat-history', text: 'Emperor Akbar abolished the jizya tax (levied on non-Muslims) in which year?', options: ['1556', '1564', '1575', '1592'], correctIndex: 1, explanation: 'Akbar abolished the jizya tax in 1564, 8 years after ascending the throne. The jizya was a poll tax levied on non-Muslim subjects in Islamic states. Akbar\'s abolition was a significant step toward his policy of religious tolerance (Sulh-i-Kul). The tax was later reinstated by Aurangzeb in 1679, causing discontent among Hindus.', source: 'Indian Council of Historical Research / Abul Fazl\'s Akbarnama', difficulty: 'medium' },
  { slug: 'hist-1857-mangal-pandey-regiment', categoryId: 'cat-history', text: 'Mangal Pandey, who triggered the 1857 revolt, belonged to which regiment of the British East India Company army?', options: ['34th Bengal Native Infantry (BNI)', '19th Bengal Native Infantry', '5th Bengal Light Cavalry', '48th Native Infantry'], correctIndex: 0, explanation: 'Mangal Pandey was a sepoy in the 34th Bengal Native Infantry (BNI) regiment. On 29 March 1857, at Barrackpore (near Calcutta), he mutinied and fired at British officers, becoming the first martyr of the 1857 revolt. He was hanged on 8 April 1857. The Indian government issued a postage stamp in his honour in 1984.', source: 'National Archives of India / Indian Army records', difficulty: 'hard' },
  { slug: 'hist-inc-split-surat-1907', categoryId: 'cat-history', text: 'The Indian National Congress split in 1907 at its Surat session between which two factions?', options: ['Moderates and Extremists (Garam Dal vs Naram Dal)', 'Congress and Muslim League', 'Swadeshi vs anti-Swadeshi', 'Socialists vs Capitalists'], correctIndex: 0, explanation: 'The INC split at its 1907 Surat session between the Moderates (Naram Dal, led by Gokhale, Pherozeshah Mehta) and the Extremists (Garam Dal, led by Tilak, Lajpat Rai, Bipin Chandra Pal, Aurobindo Ghosh). The Extremists demanded Swaraj (self-rule) and Swadeshi, while the Moderates preferred constitutional methods. The Congress reunited in 1916 (Lucknow Pact).', source: 'Indian National Congress Archives / Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'hist-dandi-march-distance-days', categoryId: 'cat-history', text: 'Gandhi\'s Dandi Salt March covered approximately how many kilometres over how many days?', options: ['200 km in 15 days', '240 miles (385 km) in 24 days', '300 km in 30 days', '150 km in 10 days'], correctIndex: 1, explanation: 'Gandhi\'s Dandi Salt March covered 240 miles (approximately 385 km) over 24 days, from 12 March to 6 April 1930. He walked from Sabarmati Ashram (Ahmedabad) to Dandi (a coastal village in Gujarat), where he broke the British salt law by making salt from seawater. 78 marchers started; thousands joined along the way.', source: 'Gandhi Memorial Museum / National Archives of India', difficulty: 'medium' },
  { slug: 'hist-cabinet-mission-plan-1946', categoryId: 'cat-history', text: 'The Cabinet Mission of 1946 proposed what constitutional arrangement for India?', options: ['Immediate partition into India and Pakistan', 'A federal India with grouping of provinces and limited central powers', 'A unitary state with no provincial autonomy', 'Continuation of British rule for 10 more years'], correctIndex: 1, explanation: 'The Cabinet Mission (March 1946), comprising Lord Pethick-Lawrence, Sir Stafford Cripps, and A.V. Alexander, proposed a federal India with three groups of provinces, limited central powers (defence, foreign affairs, communications), and a Constituent Assembly. Both the Congress and Muslim League initially accepted but later disagreed on interpretation, leading to partition in 1947.', source: 'National Archives of India / Indian Council of Historical Research', difficulty: 'hard' },
  { slug: 'hist-instrument-accession-date-jk', categoryId: 'cat-history', text: 'Maharaja Hari Singh of Jammu & Kashmir signed the Instrument of Accession to India on which date?', options: ['15 August 1947', '26 October 1947', '1 January 1948', '17 November 1947'], correctIndex: 1, explanation: 'Maharaja Hari Singh signed the Instrument of Accession on 26 October 1947, acceding Jammu & Kashmir to India. This followed tribal raids from Pakistan-supported forces. Indian troops were airlifted to Srinagar on 27 October. The accession was limited to defence, external affairs, and communications. Article 370 provided special status (abrogated in 2019).', source: 'Ministry of Home Affairs / National Archives of India', difficulty: 'medium' },
  { slug: 'hist-portuguese-goa-liberation-year', categoryId: 'cat-history', text: 'Goa was liberated from Portuguese rule in which year, through which military operation?', options: ['1947, Operation Polo', '1961, Operation Vijay', '1965, Operation Steeplechase', '1975, Operation Blue Star'], correctIndex: 1, explanation: 'Goa was liberated from Portuguese rule on 19 December 1961 through Operation Vijay. Indian armed forces entered Goa, Daman, and Diu after Portugal refused to negotiate their departure. The 36-hour military operation ended 451 years of Portuguese colonial rule. Goa became a Union Territory and later a state on 30 May 1987. Goa Liberation Day is observed on 19 December.', source: 'Ministry of Defence / Indian Armed Forces', difficulty: 'medium' },

  // ═══ cat-geography (10) ═══
  { slug: 'geo-india-brahmaputra-tibet-name', categoryId: 'cat-geography', text: 'The Brahmaputra river is known by what name in Tibet before it enters India?', options: ['Tsangpo (Yarlung Tsangpo)', 'Siang', 'Jamuna', 'Padma'], correctIndex: 0, explanation: 'The Brahmaputra is known as the Yarlung Tsangpo in Tibet. It originates from the Angsi Glacier near Mount Kailash. It flows eastward through Tibet for about 1,625 km, then turns south through a gorge (the "Great Bend") and enters Arunachal Pradesh as the Siang/Dihang. In Assam, it becomes the Brahmaputra. In Bangladesh, it merges with the Padma (Ganga) before emptying into the Bay of Bengal.', source: 'Ministry of Water Resources / Central Water Commission / Survey of India', difficulty: 'medium' },
  { slug: 'geo-india-cardamom-hills-western-ghats', categoryId: 'cat-geography', text: 'The Cardamom Hills, known for spice cultivation, are part of which mountain range?', options: ['Eastern Ghats', 'Western Ghats', 'Satpura Range', 'Aravalli Range'], correctIndex: 1, explanation: 'The Cardamom Hills are part of the Western Ghats, located in southern Kerala (Idukki district). They are named after cardamom cultivation, which thrives in the cool, moist climate. The region also produces pepper, tea, and coffee. Anamudi (2,695 m), the highest peak in the Western Ghats, is nearby in Eravikulam National Park.', source: 'Geological Survey of India / Kerala Tourism', difficulty: 'medium' },
  { slug: 'geo-india-cri-cyclone-prone-states', categoryId: 'cat-geography', text: 'Cyclones in India primarily affect the eastern coast (Bay of Bengal). Which state is most vulnerable to cyclones?', options: ['Kerala', 'Odisha (and Andhra Pradesh)', 'Maharashtra', 'Gujarat'], correctIndex: 1, explanation: 'Odisha and Andhra Pradesh are the most cyclone-prone states on India\'s eastern coast (Bay of Bengal). About 8% of India\'s land area is cyclone-prone. The 1999 Odisha Super Cyclone killed about 10,000 people, leading to improved early warning systems. The 2013 Cyclone Phailin and 2019 Cyclone Fani saw much lower casualties due to better evacuation. India\'s western coast (Arabian Sea) is less cyclone-prone but has seen increased activity recently.', source: 'India Meteorological Department (IMD) / National Disaster Management Authority (NDMA)', difficulty: 'medium' },
  { slug: 'geo-india-sundarbans-tiger-swim', categoryId: 'cat-geography', text: 'The Sundarbans, shared by India and Bangladesh, is known for tigers with what unique behavioural adaptation?', options: ['They are larger than other tigers', 'They are expert swimmers and can swim between islands', 'They hunt only at night', 'They are herbivorous'], correctIndex: 1, explanation: 'Sundarbans tigers are known as expert swimmers, capable of swimming long distances between islands in the mangrove delta. They have adapted to the estuarine environment, hunting in both land and water. The Sundarbans is the only tiger habitat in the world with a tidal mangrove ecosystem. The 2022 tiger census estimated about 101 tigers in the Indian Sundarbans.', source: 'National Tiger Conservation Authority (NTCA) / IUCN Red List / Sundarbans Tiger Reserve', difficulty: 'medium' },
  { slug: 'geo-india-largest-district-area-kutch', categoryId: 'cat-geography', text: 'Kutch district in Gujarat is India\'s largest district by area. Approximately how large is it?', options: ['About 25,000 sq km', 'About 35,000 sq km', 'About 45,674 sq km', 'About 60,000 sq km'], correctIndex: 2, explanation: 'Kutch district covers approximately 45,674 sq km — making it India\'s largest district by area (larger than some Indian states like Kerala and Manipur). Kutch features the Rann of Kutch (a salt marsh that floods during monsoon), the Great Rann, and the Little Rann. The Rann Utsav festival (Nov-Feb) showcases Kutch\'s culture, crafts, and white desert landscape.', source: 'Ministry of Home Affairs / Census of India / Gujarat Tourism', difficulty: 'medium' },
  { slug: 'geo-india-western-ghats-length-km', categoryId: 'cat-geography', text: 'The Western Ghats, a UNESCO World Heritage Site, stretch for approximately how many kilometres?', options: ['About 800 km', 'About 1,000 km', 'About 1,600 km', 'About 2,500 km'], correctIndex: 2, explanation: 'The Western Ghats stretch approximately 1,600 km (about 1,000 miles) along India\'s western coast, from Gujarat in the north to Kerala in the south, passing through Maharashtra, Goa, Karnataka, and Tamil Nadu. They are a UNESCO World Heritage Site (2012) and one of the world\'s 8 "hottest hotspots" of biological diversity. The highest peak is Anamudi (2,695 m) in Kerala.', source: 'UNESCO World Heritage List / Geological Survey of India', difficulty: 'medium' },
  { slug: 'geo-india-lakshadweep-coral-atolls', categoryId: 'cat-geography', text: 'The islands of Lakshadweep are of what geological origin?', options: ['Volcanic islands', 'Coral atolls (formed by coral growth on submerged volcanic seamounts)', 'Continental islands', 'Artificial islands'], correctIndex: 1, explanation: 'Lakshadweep islands are coral atolls — ring-shaped coral reefs that formed around submerged volcanic seamounts. As the seamounts subsided over millions of years, the coral kept growing upward, forming the atolls. Lakshadweep has 36 islands (only 10 inhabited) covering about 32 sq km. The lagoons around the atolls are rich in marine biodiversity and are popular for water sports.', source: 'Geological Survey of India / Lakshadweep Administration', difficulty: 'medium' },
  { slug: 'geo-india-rann-of-kutch-seasonal', categoryId: 'cat-geography', text: 'The Rann of Kutch transforms from a salt marsh to a white salt desert in which season?', options: ['Monsoon (June-September) — marshy', 'Dry season (October-February) — white salt desert', 'Both seasons remain dry', 'It is always marshy'], correctIndex: 1, explanation: 'The Rann of Kutch is a seasonal phenomenon: during the monsoon (June-September), it floods with seawater and becomes a vast marsh. During the dry season (October-February), the water evaporates, leaving a shimmering white salt desert. The Rann Utsav (festival) is held during the dry season (November-February) at Dhordo, showcasing the unique white desert landscape.', source: 'Geological Survey of India / Gujarat Tourism', difficulty: 'medium' },
  { slug: 'geo-india-mawsynram-rainfall-amount', categoryId: 'cat-geography', text: 'Mawsynram in Meghalaya, considered the wettest place on Earth, receives approximately how much annual rainfall?', options: ['About 5,000 mm', 'About 8,000 mm', 'About 11,872 mm', 'About 20,000 mm'], correctIndex: 2, explanation: 'Mawsynram in the East Khasi Hills of Meghalaya receives approximately 11,872 mm (about 467 inches) of rainfall annually — making it the wettest place on Earth. It receives this rain primarily from the southwest monsoon, which is funnelled by the Meghalaya hills. Nearby Cherrapunji was previously considered the wettest place. Meghalaya means "abode of clouds."', source: 'India Meteorological Department (IMD) / Guinness World Records', difficulty: 'medium' },
  { slug: 'geo-india-siachen-glacier-length', categoryId: 'cat-geography', text: 'The Siachen Glacier, the highest battlefield in the world, is approximately how long?', options: ['About 30 km', 'About 50 km', 'About 76 km', 'About 100 km'], correctIndex: 2, explanation: 'The Siachen Glacier is approximately 76 km (47 miles) long, making it the longest glacier in the Karakoram Range and the second-longest non-polar glacier in the world. It is located in the eastern Karakoram at altitudes of 3,528-5,753 m. India has maintained military presence there since Operation Meghdoot (April 1984). The extreme cold and altitude make it one of the most challenging military postings in the world.', source: 'Geological Survey of India / Ministry of Defence', difficulty: 'medium' },

  // ═══ cat-civics (10) ═══
  { slug: 'civ-const- preamble-words-added', categoryId: 'cat-civics', text: 'The words "Socialist," "Secular," and "Integrity" were added to the Preamble of the Constitution by which Amendment?', options: ['1st Amendment (1951)', '42nd Amendment (1976)', '44th Amendment (1978)', '52nd Amendment (1985)'], correctIndex: 1, explanation: 'The 42nd Constitutional Amendment Act, 1976 (during the Emergency) added the words "Socialist," "Secular," and "Integrity" to the Preamble. The original Preamble described India as a "Sovereign Democratic Republic." The amended Preamble reads: "Sovereign Socialist Secular Democratic Republic." The 44th Amendment (1978) tried to reverse some Emergency-era changes but left the Preamble intact.', source: 'Constitution of India, 42nd Amendment Act / Parliament of India', difficulty: 'medium' },
  { slug: 'civ-const-article-14-equality', categoryId: 'cat-civics', text: 'Article 14 of the Constitution guarantees "Equality before Law" and "Equal Protection of Laws." These concepts are derived from which legal traditions?', options: ['Both from Indian law', 'Equality before law from British common law; Equal protection of laws from American Constitution (14th Amendment)', 'Both from French law', 'Both from Roman law'], correctIndex: 1, explanation: 'Article 14 incorporates two concepts: "Equality before law" (a negative concept meaning no one is above the law, derived from British/A.V. Dicey\'s concept of Rule of Law) and "Equal protection of laws" (a positive concept meaning equal treatment of equals, derived from the 14th Amendment of the US Constitution). Article 14 applies to all persons, including citizens and non-citizens.', source: 'Constitution of India, Article 14 / Supreme Court of India', difficulty: 'hard' },
  { slug: 'civ-const-article-19-freedoms', categoryId: 'cat-civics', text: 'Article 19(1) guarantees six fundamental freedoms. Which of the following is NOT one of them?', options: ['Freedom of speech and expression', 'Freedom of movement throughout India', 'Freedom to own property anywhere in India', 'Freedom to reside and settle in any part of India'], correctIndex: 2, explanation: 'Freedom to own property is NOT under Article 19. The Right to Property was originally a Fundamental Right (Article 31) but was removed by the 44th Amendment (1978) and made a legal right under Article 300A. The six freedoms under Article 19(1) are: (a) speech and expression, (b) assembly, (c) association, (d) movement, (e) residence, (f) profession/occupation/trade/business.', source: 'Constitution of India, Article 19 / 44th Amendment Act, 1978', difficulty: 'medium' },
  { slug: 'civ-const-article-32-remedies', categoryId: 'cat-civics', text: 'Dr. Ambedkar called Article 32 the "heart and soul" of the Constitution. What does Article 32 provide?', options: ['The right to vote', 'The right to constitutional remedies (enforcement of Fundamental Rights through writs)', 'The right to property', 'The right to education'], correctIndex: 1, explanation: 'Article 32 provides the right to constitutional remedies — the right to approach the Supreme Court directly for enforcement of Fundamental Rights through 5 writs: Habeas Corpus, Mandamus, Prohibition, Certiorari, and Quo Warranto. Dr. Ambedkar called it the "heart and soul of the Constitution" because without it, Fundamental Rights would be meaningless. No other country grants such direct access to the highest court for rights enforcement.', source: 'Constitution of India, Article 32 / Constituent Assembly Debates', difficulty: 'medium' },
  { slug: 'civ-const-writ-habeas-corpus-meaning', categoryId: 'cat-civics', text: 'The writ "Habeas Corpus" literally means what in Latin?', options: ['You shall have the body', 'By what authority', 'We command', 'To be certified'], correctIndex: 0, explanation: '"Habeas Corpus" literally means "You shall have the body" (or "produce the body"). It is a writ issued by a court directing that a person detained be produced before it to determine if the detention is lawful. It protects against illegal detention and imprisonment. Article 32 and Article 226 empower the Supreme Court and High Courts respectively to issue this writ. Habeas Corpus has been called the "great writ of liberty."', source: 'Constitution of India, Articles 32 and 226 / Supreme Court of India', difficulty: 'medium' },
  { slug: 'civ-const-panchayat-elections-schedule', categoryId: 'cat-civics', text: 'Under Article 243K, elections to Panchayats are conducted by which body, and how often must they be held?', options: ['By Parliament, every 5 years', 'By the State Election Commission, every 5 years', 'By the Election Commission of India, every 3 years', 'By the Governor, every 4 years'], correctIndex: 1, explanation: 'Article 243K provides that Panchayat elections are conducted, supervised, and directed by the State Election Commission (not the central Election Commission of India). Elections must be held every 5 years. The State Election Commissioner is appointed by the Governor. The 73rd Amendment (1992) added Part IX to the Constitution, giving constitutional status to Panchayati Raj institutions.', source: 'Constitution of India, Article 243K / 73rd Amendment Act, 1992', difficulty: 'medium' },
  { slug: 'civ-const-municipal-elections-article', categoryId: 'cat-civics', text: 'Under Article 243U, the term of a Municipality is how many years from its first meeting?', options: ['3 years', '4 years', '5 years', '6 years'], correctIndex: 2, explanation: 'Article 243U (inserted by the 74th Amendment, 1992) provides that every Municipality has a term of 5 years from the date of its first meeting. If dissolved earlier, elections must be held within 6 months. The 74th Amendment gave constitutional status to urban local bodies (Municipalities) through Part IXA of the Constitution.', source: 'Constitution of India, Article 243U / 74th Amendment Act, 1992', difficulty: 'medium' },
  { slug: 'civ-const-scheduled-areas-fifth', categoryId: 'cat-civics', text: 'The Fifth Schedule of the Constitution deals with the administration and control of which areas?', options: ['Scheduled Castes', 'Scheduled Areas and Scheduled Tribes in states (other than Assam, Meghalaya, Tripura, Mizoram)', 'Scheduled Languages', 'Tribal areas of Northeast India'], correctIndex: 1, explanation: 'The Fifth Schedule deals with the administration and control of Scheduled Areas and Scheduled Tribes in any state (except the four northeastern states of Assam, Meghalaya, Tripura, and Mizoram, which are covered under the Sixth Schedule). The President can declare any area a "Scheduled Area." A Tribal Advisory Council advises on welfare of STs. The Fifth Schedule has 10 states with Scheduled Areas.', source: 'Constitution of India, Fifth Schedule', difficulty: 'hard' },
  { slug: 'civ-const-sixth-schedule-autonomous', categoryId: 'cat-civics', text: 'The Sixth Schedule of the Constitution provides for Autonomous District Councils in which states?', options: ['Jharkhand, Odisha, Chhattisgarh', 'Assam, Meghalaya, Tripura, Mizoram', 'Bihar, West Bengal, Jharkhand', 'Kerala, Tamil Nadu, Karnataka'], correctIndex: 1, explanation: 'The Sixth Schedule provides for Autonomous District Councils in 4 northeastern states: Assam, Meghalaya, Tripura, and Mizoram (added later). As of 2024, there are 10 Autonomous District Councils. These councils have powers over land, forests, agriculture, and local justice. The PESA Act (1996) extends similar self-governance to Fifth Schedule areas.', source: 'Constitution of India, Sixth Schedule', difficulty: 'hard' },
  { slug: 'civ-const-office-profit-meaning', categoryId: 'cat-civics', text: 'Under Article 102(1)(a), a person is disqualified from being a member of Parliament if they hold an "Office of Profit." What does this mean?', options: ['A profitable private business', 'An office under the Government that carries remuneration (salary, perks) that could compromise independence', 'Any salaried position including private sector', 'A government office that pays above a certain amount'], correctIndex: 1, explanation: 'An "Office of Profit" refers to an office under the Central or State Government that carries remuneration (salary, allowances, or other benefits) which could compromise the independence of the member and create a conflict of interest. The intent is to prevent the executive from influencing legislators by offering them positions. Parliament has enacted the Parliament (Prevention of Disqualification) Act, 1959 (amended several times) to specify which offices are exempt.', source: 'Constitution of India, Article 102(1)(a) / Parliament (Prevention of Disqualification) Act, 1959', difficulty: 'hard' },

  // ═══ cat-science (10) ═══
  { slug: 'sci-isro-aditya-l1-orbit-type', categoryId: 'cat-science', text: 'ISRO\'s Aditya-L1 solar mission was placed in what type of orbit around the Sun?', options: ['Low Earth Orbit', 'Halo orbit around the L1 Lagrange point (between Earth and Sun)', 'Geostationary orbit', 'Polar solar orbit'], correctIndex: 1, explanation: 'Aditya-L1 was placed in a halo orbit around the L1 Lagrange point — a gravitationally stable point between the Earth and Sun (about 1.5 million km from Earth). This orbit allows continuous observation of the Sun without eclipses or occultation. Aditya-L1 was launched on 2 September 2023 and reached L1 on 6 January 2024. It carries 7 instruments to study the solar corona, solar wind, and CMEs.', source: 'ISRO official website / Department of Space', difficulty: 'medium' },
  { slug: 'sci-india-ntpc-largest-power-producer', categoryId: 'cat-science', text: 'NTPC Limited is India\'s largest power generating company. What does NTPC stand for (as rebranded)?', options: ['National Thermal Power Corporation', 'NTPC Limited (rebranded; formerly National Thermal Power Corporation)', 'National Transmission Power Corporation', 'Nuclear Thermal Power Corporation'], correctIndex: 1, explanation: 'NTPC was originally established as "National Thermal Power Corporation Limited" in 1975. It was rebranded as "NTPC Limited" in 2005 to reflect its diversified portfolio beyond thermal power — including solar, hydro, and wind. NTPC is India\'s largest power generator with an installed capacity of about 76 GW (as of 2024). It is a Maharatna CPSE (Central Public Sector Enterprise) under the Ministry of Power.', source: 'NTPC Limited / Ministry of Power, Government of India', difficulty: 'medium' },
  { slug: 'sci-india-csir-labs-count', categoryId: 'cat-science', text: 'The Council of Scientific and Industrial Research (CSIR), India\'s largest R&D organisation, operates how many laboratories/institutes across India?', options: ['About 18', 'About 37-38', 'About 50', 'About 75'], correctIndex: 1, explanation: 'CSIR operates approximately 37-38 national laboratories and institutes across India. Established in 1942, it is an autonomous body under the Department of Scientific and Industrial Research (DSIR), Ministry of Science and Technology. CSIR has about 4,500 scientists and 10,000 technical staff. Notable CSIR labs include CSIR-DRDO, CSIR-IITR, CSIR-CEERI, CSIR-NCL, and CSIR-CMERI. CSIR files about 200 patents annually.', source: 'Council of Scientific and Industrial Research (CSIR) / Ministry of Science and Technology', difficulty: 'medium' },
  { slug: 'sci-india-green-revolution-crops-wheat', categoryId: 'cat-science', text: 'The Green Revolution in India (1960s-70s) primarily boosted the production of which crop(s)?', options: ['Rice only', 'Wheat primarily, then rice', 'Cotton and jute', 'Tea and coffee'], correctIndex: 1, explanation: 'The Green Revolution primarily boosted wheat production in India. High-Yielding Variety (HYV) wheat seeds (developed by Norman Borlaug, Nobel Peace Prize 1970) were introduced in Punjab, Haryana, and western UP. M.S. Swaminathan was the key Indian scientist. Wheat production increased from 11 million tonnes (1965) to about 113 million tonnes (2023-24). Rice production also increased but more gradually. India is now the 2nd largest producer of both wheat and rice.', source: 'Indian Council of Agricultural Research (ICAR) / Ministry of Agriculture', difficulty: 'medium' },
  { slug: 'sci-india-milk-revolution-operation-flood', categoryId: 'cat-science', text: '"Operation Flood," launched in 1970, transformed India from a milk-deficient nation to the world\'s largest milk producer. Who led this initiative?', options: ['M.S. Swaminathan', 'Verghese Kurien (the "Father of the White Revolution" in India)', 'Norman Borlaug', 'Anna Hazare'], correctIndex: 1, explanation: 'Verghese Kurien (1921-2012), known as the "Father of the White Revolution" in India, led Operation Flood (1970-1996). It created the "Amul" model of dairy cooperatives, making India the world\'s largest milk producer (from about 21 million tonnes in 1970 to about 230 million tonnes in 2023-24). Kurien founded the National Dairy Development Board (NDDB) and GCMMF (Amul). He received the World Food Prize in 1989.', source: 'National Dairy Development Board (NDDB) / GCMMF (Amul)', difficulty: 'medium' },
  { slug: 'sci-india-isro-chandrayaan-3-vikram-landing', categoryId: 'cat-science', text: 'Chandrayaan-3\'s Vikram lander used which advanced technology for its autonomous landing on the Moon?', options: ['GPS navigation', 'AI-powered hazard detection and avoidance system (using sensors and cameras)', 'Manual remote control from Earth', 'Pre-programmed trajectory only'], correctIndex: 1, explanation: 'Vikram used an AI-powered hazard detection and avoidance system (HDA) with sensors (velocimeters, altimeters) and cameras (hazard avoidance camera) to autonomously identify a safe landing site on the lunar surface. The lander scanned the surface for hazards (craters, boulders) and adjusted its trajectory in real-time during the final descent — the most critical phase. This was an improvement over Chandrayaan-2\'s failed landing (2019).', source: 'ISRO official website / Chandrayaan-3 mission report', difficulty: 'hard' },
  { slug: 'sci-india-vaccine-pfizer-vs-covishield', categoryId: 'cat-science', text: 'India did not grant emergency use authorisation to the Pfizer-BioNTech COVID-19 vaccine, primarily because of what concern?', options: ['The vaccine was not effective', 'Pfizer demanded legal indemnity (protection from liability for side effects) which India refused', 'The vaccine was too expensive', 'India had enough vaccines'], correctIndex: 1, explanation: 'India did not authorise the Pfizer-BioNTech vaccine because Pfizer demanded legal indemnity — protection from legal liability in case of adverse side effects. India\'s drug regulatory authority (DCGI) refused to grant blanket indemnity, as this is typically not granted to foreign manufacturers in India. Instead, India used Covishield (SII/AstraZeneca-Oxford), Covaxin (Bharat Biotech), and Sputnik V — none of which demanded indemnity.', source: 'Drugs Controller General of India (DCGI) / Ministry of Health', difficulty: 'medium' },
  { slug: 'sci-india-isro-rediscover-vikram', categoryId: 'cat-science', text: 'ISRO\'s Chandrayaan-1 mission (2008) discovered what on the Moon that revolutionised lunar science?', options: ['Evidence of water molecules on the lunar surface', 'Lunar magnetic field', 'Lunar atmosphere', 'Evidence of past life'], correctIndex: 0, explanation: 'Chandrayaan-1 (launched October 2008) discovered evidence of water molecules (OH/H2O) on the lunar surface, primarily near the poles, using its Moon Mineralogy Mapper (M3) instrument. This was a groundbreaking discovery that changed the understanding of the Moon\'s geology and opened possibilities for future lunar habitation. The discovery was confirmed by NASA. Chandrayaan-1 also carried the Moon Impact Probe (MIP) which crash-landed near the south pole.', source: 'ISRO / NASA / Brown University (M3 instrument)', difficulty: 'medium' },
  { slug: 'sci-india-bhabha-cancer-research', categoryId: 'cat-science', text: 'The Tata Memorial Centre (TMC), India\'s premier cancer research and treatment institution, is located in which city?', options: ['Bengaluru', 'Mumbai', 'Delhi', 'Chennai'], correctIndex: 1, explanation: 'The Tata Memorial Centre (TMC) is located in Mumbai. It was established in 1941 as the Tata Memorial Hospital by the Sir Dorabji Tata Trust. In 1962, it became a grant-in-aid institution under the Department of Atomic Energy. TMC is India\'s largest and most advanced cancer treatment and research centre, treating over 100,000 new patients annually. It also conducts the National Cancer Grid (NCG) connecting 270+ cancer centres across India.', source: 'Tata Memorial Centre / Department of Atomic Energy / Ministry of Health', difficulty: 'medium' },
  { slug: 'sci-india-geothermal-energy-puga', categoryId: 'cat-science', text: 'India\'s first geothermal power project was approved in 2021 in which region?', options: ['Gujarat', 'Puga Valley, Ladakh', 'Maharashtra', 'Odisha'], correctIndex: 1, explanation: 'India\'s first geothermal power project was approved in 2021 at Puga Valley, Ladakh. A Memorandum of Understanding (MoU) was signed between ONGC Energy Centre and the Ladakh administration for a 1 MW pilot geothermal plant. Puga Valley has geothermal potential due to the Himalayan geothermal belt. India has an estimated geothermal potential of about 10,000 MW, but commercial exploitation has been limited.', source: 'Ministry of New and Renewable Energy (MNRE) / ONGC Energy Centre', difficulty: 'hard' },

  // ═══ cat-sports (10) ═══
  { slug: 'spt-india-cricket-test-400-wickets-anil', categoryId: 'cat-sports', text: 'Anil Kumble took 619 Test wickets — the most by any Indian bowler. He achieved which unique feat against Pakistan at Delhi in 1999?', options: ['First 10-wicket haul in an innings', 'All 10 wickets in a single innings (10/74)', 'First hat-trick by an Indian', 'First to score a century and take 10 wickets in a Test'], correctIndex: 1, explanation: 'Anil Kumble took all 10 wickets in a single innings (10/74) against Pakistan at the Feroz Shah Kotla (now Arun Jaitley Stadium), Delhi, in February 1999. He became only the second bowler in Test cricket history to take all 10 wickets in an innings (after Jim Laker of England, 10/53 vs Australia in 1956). Ajaz Patel (NZ) later achieved this feat in 2021. Kumble finished with 619 Test wickets (3rd highest all-time).', source: 'ESPN Cricinfo / ICC records / BCCI', difficulty: 'medium' },
  { slug: 'spt-india-cricket-test-200-sachin-first', categoryId: 'cat-sports', text: 'Sachin Tendulkar was the first batsman to score a double century (200+) in One Day International (ODI) cricket. Against which team and in which year?', options: ['Sri Lanka, 2009', 'South Africa, 2010 (Gwalior)', 'Australia, 2011', 'Pakistan, 2012'], correctIndex: 1, explanation: 'Sachin Tendulkar scored the first double century (200 not out) in ODI cricket on 24 February 2010 against South Africa at the Captain Roop Singh Stadium, Gwalior. He faced 147 balls and hit 25 fours and 3 sixes. Rohit Sharma later scored 3 ODI double centuries (209, 264, 208*), and Virender Sehwag scored one (219). Sachin retired from ODIs in 2012 with 18,426 runs — the most in ODI history.', source: 'ESPN Cricinfo / ICC records / BCCI', difficulty: 'medium' },
  { slug: 'spt-india-hockey-dhyan-chand-record', categoryId: 'cat-sports', text: 'Major Dhyan Chand, India\'s legendary hockey player, scored how many goals in the 1928 Amsterdam Olympics (India\'s first Olympic hockey gold)?', options: ['7 goals', '14 goals', '18 goals', '25 goals'], correctIndex: 1, explanation: 'Dhyan Chand scored 14 goals in the 1928 Amsterdam Olympics, where India won its first Olympic hockey gold medal. He scored 2 goals in the final against the Netherlands (3-0 win). In his Olympic career (1928, 1932, 1936), Dhyan Chand scored 33 goals in 12 matches across 3 Olympics. His birthday (29 August) is celebrated as National Sports Day in India.', source: 'International Hockey Federation (FIH) / Indian Olympic Association', difficulty: 'hard' },
  { slug: 'spt-india-badminton-thomas-cup-contribution', categoryId: 'cat-sports', text: 'In India\'s historic Thomas Cup 2022 victory, which player won the crucial first singles match in the final against Indonesia?', options: ['Kidambi Srikanth', 'Lakshya Sen', 'HS Prannoy', 'Sai Praneeth'], correctIndex: 1, explanation: 'Lakshya Sen won the crucial first singles match against Anthony Sinisuka Ginting (Indonesia) in the Thomas Cup 2022 final. Sen won 8-21, 21-17, 21-16 in a come-from-behind victory. The doubles pair of Satwiksairaj Rankireddy and Chirag Shetty won the second match, and Kidambi Srikanth won the third. India won 3-0 in the final — their first Thomas Cup title since the tournament began in 1949.', source: 'Badminton World Federation (BWF) / Badminton Association of India', difficulty: 'hard' },
  { slug: 'spt-india-boxing-mary-kom-olympic', categoryId: 'cat-sports', text: 'Mary Kom won India\'s first Olympic boxing medal (bronze) at the 2012 London Olympics. In what weight category did she compete?', options: ['48 kg (light flyweight)', '51 kg (flyweight)', '54 kg (bantamweight)', '57 kg (featherweight)'], correctIndex: 1, explanation: 'Mary Kom competed in the 51 kg flyweight category at the 2012 London Olympics, the first Olympics to include women\'s boxing. She won a bronze medal, becoming the first Indian woman to win an Olympic boxing medal. She was a 6-time World Amateur Boxing Champion (2002, 2005, 2006, 2008, 2010, 2018) — the most by any boxer. She also won gold at the 2018 Commonwealth Games and was a Rajya Sabha MP.', source: 'International Olympic Committee (IOC) / Boxing Federation of India', difficulty: 'medium' },
  { slug: 'spt-india-athletics-milkha-rome', categoryId: 'cat-sports', text: 'Milkha Singh, the "Flying Sikh," missed an Olympic bronze by 1/100th of a second in the 400m at which Olympics?', options: ['Melbourne 1956', 'Rome 1960', 'Tokyo 1964', 'Helsinki 1952'], correctIndex: 1, explanation: 'Milkha Singh finished 4th in the 400m final at the 1960 Rome Olympics, missing the bronze medal by 1/100th of a second. His time was 45.73 seconds. He was the first Indian to reach an Olympic track final. He also won India\'s first individual Commonwealth Games gold (440 yards, 1958 Cardiff). The biopic "Bhaag Milkha Bhaag" (2013) was based on his life. He was awarded the Padma Shri in 1959.', source: 'International Olympic Committee (IOC) / Athletics Federation of India', difficulty: 'medium' },
  { slug: 'spt-india-chess-anand-gm-year', categoryId: 'cat-sports', text: 'Viswanathan Anand became India\'s first chess Grandmaster in which year?', options: ['1985', '1987', '1988', '1991'], correctIndex: 2, explanation: 'Viswanathan Anand became India\'s first Grandmaster (GM) in 1988 at the age of 18. He won the World Junior Chess Championship in 1987. He later became World Chess Champion (2000, 2007-2013). He was awarded the Padma Shri (1988), Padma Bhushan (2000), and Padma Vibhushan (2007). He is from Chennai, Tamil Nadu. After him, India has produced over 80 Grandmasters (as of 2024).', source: 'World Chess Federation (FIDE)', difficulty: 'medium' },
  { slug: 'spt-india-cricket-bumrah-no1-test', categoryId: 'cat-sports', text: 'Jasprit Bumrah became the first Indian fast bowler to reach No.1 in the ICC Test bowling rankings in which year?', options: ['2019', '2021', '2024', '2023'], correctIndex: 2, explanation: 'Jasprit Bumrah became the first Indian fast bowler to reach No.1 in the ICC Test bowling rankings in February 2024, after his performance in the Test series against England. Bumrah surpassed Ravichandran Ashwin and Ravindra Jadeja (spinners) who had previously reached No.1 for India. Bumrah is known for his unique action, yorkers, and ability to bowl across formats.', source: 'ICC rankings / ESPN Cricinfo / BCCI', difficulty: 'medium' },
  { slug: 'spt-india-football-chhetri-asian-cup', categoryId: 'cat-sports', text: 'Sunil Chhetri scored India\'s first goal at the AFC Asian Cup in 2019. Against which team?', options: ['Thailand (4-1 win)', 'UAE', 'Bahrain', 'Qatar'], correctIndex: 0, explanation: 'Sunil Chhetri scored 2 goals in India\'s 4-1 win over Thailand at the 2019 AFC Asian Cup in Abu Dhabi. India\'s 4-1 victory was their biggest Asian Cup win and their first Asian Cup win since 1984. Chhetri scored a total of 2 goals in that tournament. India did not advance from the group stage. Chhetri retired from international football in June 2024 with 94 goals in 151 matches.', source: 'Asian Football Confederation (AFC) / All India Football Federation (AIFF)', difficulty: 'hard' },
  { slug: 'spt-india-para-athletics-sumit-antill', categoryId: 'cat-sports', text: 'Sumit Antill set a world record throw to win Paralympic gold for India at the Tokyo 2020 Paralympics. In which event?', options: ['Javelin throw (F64 category) — 68.55 m', 'Shot put', 'Discus throw', 'Club throw'], correctIndex: 0, explanation: 'Sumit Antill won gold in the men\'s javelin throw F64 category at the Tokyo 2020 Paralympics (held 2021) with a world record throw of 68.55 m. He broke his own world record (66.95 m) set earlier that year. He lost his left leg below the knee in a tractor accident at age 8. At Paris 2024, he defended his gold with a Paralympic record of 70.59 m.', source: 'International Paralympic Committee (IPC) / Paralympic Committee of India', difficulty: 'medium' },

  // ═══ cat-culture (10) ═══
  { slug: 'cul-onam-mahabali-myth', categoryId: 'cat-culture', text: 'Onam, the harvest festival of Kerala, is celebrated to welcome which mythical king?', options: ['Lord Rama', 'King Mahabali (the benevolent Asura king)', 'Lord Krishna', 'Emperor Ashoka'], correctIndex: 1, explanation: 'Onam is celebrated to welcome the return of the legendary King Mahabali, a benevolent Asura (demon) king who ruled Kerala in Hindu mythology. According to legend, Lord Vishnu (in his Vamana avatar) pushed Mahabali to the netherworld (Patala) but granted him permission to visit his subjects once a year — celebrated as Onam. The 10-day festival (August-September) features flower carpets (pookalam), the Onasadya feast, boat races, and Kathakali performances.', source: 'Ministry of Culture / Kerala Tourism', difficulty: 'medium' },
  { slug: 'cul-dussehra-vijayadashami-meaning', categoryId: 'cat-culture', text: 'Dussehra (Vijayadashami) marks the victory of good over evil. In North India, it celebrates whose victory over whom?', options: ['Krishna over Kansa', 'Lord Rama\'s victory over Ravana (10-headed demon king of Lanka)', 'Arjuna over the Kauravas', 'Goddess Durga over Mahishasura'], correctIndex: 1, explanation: 'In North India, Dussehra (Vijayadashami) celebrates Lord Rama\'s victory over the 10-headed demon king Ravana of Lanka. It is celebrated on the 10th day of Navratri (Ashwin month). Effigies of Ravana, Kumbhakarna, and Meghnad are burned. In eastern India (especially West Bengal), Dussehra coincides with Durga Puja, celebrating Goddess Durga\'s victory over the buffalo demon Mahishasura.', source: 'Ministry of Culture / Department of Tourism', difficulty: 'easy' },
  { slug: 'cul-thanjavur-brihadeshwara-vimana-height', categoryId: 'cat-culture', text: 'The vimana (tower) of the Brihadeshwara Temple at Thanjavur is approximately how tall?', options: ['About 30 m', 'About 50 m', 'About 66 m (216 ft)', 'About 100 m'], correctIndex: 2, explanation: 'The vimana (tower) of the Brihadeshwara Temple is approximately 66 m (216 ft) tall — one of the tallest temple towers in India. It was built by Rajaraja Chola I (completed c. 1010 CE) and is made entirely of granite. The tower is topped by an 80-tonne monolithic cupola (shikhara). The temple is a UNESCO World Heritage Site, part of the "Great Living Chola Temples."', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-kathakali-green-makeup-pacha', categoryId: 'cat-culture', text: 'In Kathakali dance-drama, the "Pacha" (green) makeup type is used to represent which type of character?', options: ['Demons and villains', 'Noble, heroic, and divine characters (like Rama, Krishna, Arjuna)', 'Female characters', 'Sage/hermit characters'], correctIndex: 1, explanation: 'Pacha (green) makeup in Kathakali represents noble, heroic, and divine characters — such as Rama, Krishna, Arjuna, and Bhima. The face is painted green with white markings around the eyes. Other makeup types: Kathi (knife, for villainous-noble characters like Ravana and Duryodhana), Kari (black, for demonesses), Thadi (beard, for various types: red, white, black), and Minukku (radiant, for female and gentle male characters).', source: 'Sangeet Natak Akademi / Kerala Kalamandalam', difficulty: 'medium' },
  { slug: 'cul-ratha-yatra-three-chariots-name', categoryId: 'cat-culture', text: 'During the Puri Rath Yatra, the chariot of Lord Jagannath is called what?', options: ['Taladhwaja', 'Nandighosha (or Nandighosh)', 'Darpadalan', 'Garuda'], correctIndex: 1, explanation: 'Lord Jagannath\'s chariot is called Nandighosha (45.6 ft tall, 18 wheels, yellow-red canopy). Balabhadra\'s chariot is Taladhwaja (44 ft, 16 wheels, green-red canopy). Subhadra\'s chariot is Darpadalan (43 ft, 14 wheels, black-red canopy). Each chariot is newly constructed every year from specific types of wood (phasi, dasa, etc.) by hereditary carpenter families (Maharana) in Puri, Odisha.', source: 'Jagannath Temple Administration / Department of Tourism, Odisha', difficulty: 'hard' },
  { slug: 'cul-kuchipudi-tarangam-unique', categoryId: 'cat-culture', text: 'Kuchipudi dance has a unique feature called "Tarangam" — what is it?', options: ['Dancing on the edge of a brass plate while balancing a pot of water on the head', 'Singing while dancing', 'Using fire as a prop', 'Performing only with masks'], correctIndex: 0, explanation: 'Tarangam is a unique feature of Kuchipudi where the dancer performs on the edge of a brass plate (sometimes while balancing a pot of water or lit lamps on the head). This demonstrates the dancer\'s balance, control, and skill. Tarangam is performed to devotional songs about Lord Krishna. The brass plate represents the universe. Kuchipudi originated in the village of Kuchipudi in Andhra Pradesh and was traditionally performed by Brahmin men.', source: 'Sangeet Natak Akademi / Andhra Pradesh Tourism', difficulty: 'hard' },
  { slug: 'cul-pattachitra-origin-puri', categoryId: 'cat-culture', text: 'Pattachitra painting, a traditional cloth-based scroll painting, originates from which temple town?', options: ['Madurai', 'Puri (and Raghurajpur, Odisha)', 'Tirupati', 'Thanjavur'], correctIndex: 1, explanation: 'Pattachitra originates from Puri and the nearby village of Raghurajpur in Odisha. The word "Patta" means cloth and "Chitra" means picture. The paintings traditionally depict Lord Jagannath, the 10 incarnations of Vishnu (Dashavatara), and scenes from the Ramayana and Mahabharata. They use natural colours and are painted on treated cloth or dried palm leaves. Pattachitra received a GI (Geographical Indication) tag.', source: 'Ministry of Culture / Odisha Tourism / Geographical Indications Registry', difficulty: 'medium' },
  { slug: 'cul-indian-music-system-sruti', categoryId: 'cat-culture', text: 'In Indian classical music (both Hindustani and Carnatic), the octave is traditionally divided into how many "srutis" (microtones)?', options: ['12 srutis (like the Western system)', '22 srutis', '24 srutis', '36 srutis'], correctIndex: 1, explanation: 'The Indian classical music octave is traditionally divided into 22 srutis (microtones), as described in ancient texts like Bharata\'s "Natya Shastra" (c. 200 BCE - 200 CE). While there are 7 swaras (notes: Sa, Re, Ga, Ma, Pa, Dha, Ni) and 12 semitones (shuddha + vikrita swaras), the 22 srutis represent finer subdivisions. The Western system uses 12 equal-tempered semitones. The sruti system allows for subtle pitch variations characteristic of Indian music.', source: 'Sangeet Natak Akademi / Natya Shastra', difficulty: 'hard' },
  { slug: 'cul-jaipur-jantar-mantar-instruments-count', categoryId: 'cat-culture', text: 'The Jantar Mantar observatory in Jaipur, a UNESCO World Heritage Site, contains how many instruments (yantras)?', options: ['5', '10', '19', '25'], correctIndex: 2, explanation: 'Jantar Mantar in Jaipur contains 19 instruments (yantras) for astronomical observation. Built by Maharaja Sawai Jai Singh II between 1728-1734, it is the largest of 5 Jantar Mantar observatories (the others are in Delhi, Ujjain, Mathura, and Varanasi). The Samrat Yantra (sundial) at Jaipur is the world\'s largest stone sundial, accurate to 2 seconds. The instruments were used to measure time, predict eclipses, and track stars.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },
  { slug: 'cul-hampi-vittala-stone-chariot', categoryId: 'cat-culture', text: 'The famous Stone Chariot at Hampi is located in front of which temple?', options: ['Virupaksha Temple', 'Vittala Temple (Vittala Temple complex)', 'Hazara Rama Temple', 'Achyutaraya Temple'], correctIndex: 1, explanation: 'The Stone Chariot is located in the Vittala Temple complex at Hampi. It is one of India\'s most iconic structures — a miniature temple carved in the shape of a chariot, dedicated to Garuda (the vehicle of Lord Vishnu). The chariot\'s wheels were originally functional (could rotate). The Vittala Temple complex also features 56 musical pillars that produce different musical notes when tapped. Hampi is a UNESCO World Heritage Site.', source: 'UNESCO World Heritage List / Archaeological Survey of India', difficulty: 'medium' },

  // ═══ cat-economy (10) ═══
  { slug: 'eco-india-npci-establishment', categoryId: 'cat-economy', text: 'The National Payments Corporation of India (NPCI), which operates UPI, was established in which year?', options: ['2005', '2008', '2012', '2016'], correctIndex: 2, explanation: 'NPCI was established in 2008 (incorporated on 17 December 2007, began operations in 2009) as an umbrella organisation for retail payment systems in India. It is a not-for-profit company promoted by RBI and major banks. NPCI launched IMPS (2010), RuPay (2012), UPI (2016), FASTag (2016), and Bharat Bill Pay (2017). NPCI processes billions of transactions monthly. UPI is NPCI\'s flagship product.', source: 'National Payments Corporation of India (NPCI) / RBI', difficulty: 'medium' },
  { slug: 'eco-india-sebi-establishment', categoryId: 'cat-economy', text: 'The Securities and Exchange Board of India (SEBI) was given statutory status in which year?', options: ['1988', '1992', '1995', '2000'], correctIndex: 1, explanation: 'SEBI was initially established as an administrative body in 1988 but was given statutory status by the SEBI Act, 1992 (passed after the 1991 economic liberalisation). SEBI regulates the securities market (stock exchanges, brokers, mutual funds, etc.). It has three functions: quasi-legislative (makes regulations), quasi-executive (enforces regulations), and quasi-judicial (passes orders). SEBI is headquartered in Mumbai (BKC).', source: 'Securities and Exchange Board of India (SEBI) / Ministry of Finance', difficulty: 'medium' },
  { slug: 'eco-india-lic-nationalisation-year', categoryId: 'cat-economy', text: 'The insurance sector in India was nationalised (creating LIC) in which year?', options: ['1947', '1956', '1969', '1973'], correctIndex: 1, explanation: 'The insurance sector was nationalised on 1 September 1956, when 245 private insurance companies were merged to form the Life Insurance Corporation of India (LIC). The LIC Act, 1956 created the monopoly. In 1999, the Insurance Regulatory and Development Authority (IRDA, now IRDAI) was established, and the sector was opened to private companies. India allowed 74% FDI in insurance in 2021.', source: 'Life Insurance Corporation of India / IRDAI / Ministry of Finance', difficulty: 'medium' },
  { slug: 'eco-india-rbi-establishment-date', categoryId: 'cat-economy', text: 'The Reserve Bank of India (RBI) was established on which date?', options: ['1 April 1935', '15 August 1947', '1 January 1949', '1 April 1947'], correctIndex: 0, explanation: 'The RBI was established on 1 April 1935 under the RBI Act, 1934. It was initially a private shareholders\' bank. It was nationalised on 1 January 1949. The RBI is India\'s central bank, responsible for monetary policy, currency issuance, banking supervision, and foreign exchange management. It is headquartered in Mumbai. The RBI Governor chairs the Monetary Policy Committee (MPC, established 2016). The first Governor was Osborne Smith (1935).', source: 'Reserve Bank of India', difficulty: 'medium' },
  { slug: 'eco-india-banking-nationalisation-1969', categoryId: 'cat-economy', text: 'In 1969, the Government of India nationalised how many major commercial banks?', options: ['7', '10', '14', '20'], correctIndex: 2, explanation: 'On 19 July 1969, the Government of India nationalised 14 major commercial banks (each with deposits exceeding Rs. 50 crore), including Bank of India, Canara Bank, Punjab National Bank, and Union Bank. The aim was to expand credit to priority sectors (agriculture, small industry). In 1980, 6 more banks were nationalised. Currently, India has 12 nationalised banks (after mergers). SBI was already government-owned since 1955.', source: 'Reserve Bank of India / Ministry of Finance', difficulty: 'medium' },
  { slug: 'eco-india-gst-launch-date', categoryId: 'cat-economy', text: 'The Goods and Services Tax (GST) was implemented in India from which date?', options: ['1 April 2017', '1 July 2017', '1 October 2017', '1 January 2018'], correctIndex: 1, explanation: 'GST was implemented on 1 July 2017, replacing multiple central and state indirect taxes (excise duty, service tax, VAT, CST, octroi, etc.). It was called "one nation, one tax." GST has 5 main rate slabs: 0%, 5%, 12%, 18%, 28% (plus special rates for gold/diamonds at 3% and luxury/sin goods at 40%). The GST Council (chaired by the Finance Minister) decides rates. The 101st Constitutional Amendment (2016) enabled GST.', source: 'GST Council / Ministry of Finance / CBIC', difficulty: 'easy' },
  { slug: 'eco-india-fdi-defence-sector', categoryId: 'cat-economy', text: 'As of 2020, what is the maximum FDI permitted under the automatic route in India\'s defence sector?', options: ['26%', '49%', '74%', '100%'], correctIndex: 2, explanation: 'As of 2020, India permits up to 74% FDI under the automatic route in the defence sector (increased from 49%). FDI above 74% up to 100% requires government approval, particularly for access to modern technology. The Defence Manufacturing Policy aims to make India self-reliant in defence production ("Atmanirbhar Bharat"). India is the world\'s 2nd largest arms importer (after Saudi Arabia, SIPRI data).', source: 'Department for Promotion of Industry and Internal Trade (DPIIT) / Ministry of Defence', difficulty: 'hard' },
  { slug: 'eco-india-startup-india-features', categoryId: 'cat-economy', text: 'Under the "Startup India" initiative, which of the following benefits are available to recognised startups?', options: ['Tax exemption for 3 years, self-certification, faster patent filing, easier public procurement', 'Guaranteed government funding', 'Mandatory government contracts', 'Monopoly rights in their sector'], correctIndex: 0, explanation: 'Startup India (launched 16 January 2016) provides: 3-year tax holiday (under Section 80-IAC), self-certification for labour/environment compliance, 80% rebate on patent fees, faster patent examination, easier public procurement (exemption from prior experience/turnover criteria), and Fund of Funds (FFS) for startups (Rs. 10,000 crore corpus). DPIIT (Department for Promotion of Industry and Internal Trade) recognises startups.', source: 'Department for Promotion of Industry and Internal Trade (DPIIT) / Startup India', difficulty: 'medium' },
  { slug: 'eco-india-rupay-card-network', categoryId: 'cat-economy', text: 'RuPay is India\'s domestic card payment network. It was launched by which organisation?', options: ['Visa', 'Mastercard', 'National Payments Corporation of India (NPCI)', 'SBI'], correctIndex: 2, explanation: 'RuPay was launched by NPCI (National Payments Corporation of India) on 26 March 2012. It is India\'s domestic card payment network (like China\'s UnionPay). RuPay cards are accepted at all ATMs, POS terminals, and online merchants in India. RuPay also has international acceptance (Discover, JCB, and UnionPay networks). By 2024, over 700 million RuPay cards had been issued. RuPay is cheaper for merchants than Visa/Mastercard.', source: 'National Payments Corporation of India (NPCI) / RBI', difficulty: 'medium' },
  { slug: 'eco-india-e-way-bill-gst', categoryId: 'cat-economy', text: 'Under GST, an "E-Way Bill" is required for the movement of goods exceeding what value?', options: ['Rs. 10,000', 'Rs. 25,000', 'Rs. 50,000', 'Rs. 1,00,000'], correctIndex: 2, explanation: 'Under GST, an E-Way Bill is required for the movement of goods exceeding Rs. 50,000 in value within a state or between states. It is generated electronically on the GST portal (ewaybillgst.gov.in) or via SMS. The E-Way Bill contains details of the consignor, consignee, goods, transporter, and vehicle. It helps track the movement of goods and prevent tax evasion. It was introduced on 1 April 2018 for inter-state movement and gradually extended to intra-state.', source: 'GST Council / CBIC / National Informatics Centre (NIC)', difficulty: 'medium' },

  // ═══ cat-environment (10) ═══
  { slug: 'env-india-cheetah-reintroduction-2022', categoryId: 'cat-environment', text: 'India reintroduced cheetahs (from Namibia and South Africa) at which national park in 2022?', options: ['Ranthambore National Park (Rajasthan)', 'Kuno National Park (Madhya Pradesh)', 'Gir National Park (Gujarat)', 'Sariska Tiger Reserve (Rajasthan)'], correctIndex: 1, explanation: 'India reintroduced cheetahs (declared extinct in India in 1952) at Kuno National Park, Madhya Pradesh, on 17 September 2022. Eight cheetahs were brought from Namibia, followed by 12 more from South Africa in February 2023. The project is called "Project Cheetah." The cheetahs are being kept in enclosures before full release. Some cubs have been born. Kuno was selected for its suitable habitat (grasslands) and prey base.', source: 'Ministry of Environment, Forest and Climate Change / NTCA / Wildlife Institute of India', difficulty: 'medium' },
  { slug: 'env-india-snow-leopard-spa-cities', categoryId: 'cat-environment', text: 'The Snow Leopard Population Assessment in India (SPAI) found snow leopards in how many states/UTs?', options: ['3', '4', '5', '7'], correctIndex: 2, explanation: 'The SPAI (released January 2024) found snow leopards in 5 states/UTs: Ladakh, Himachal Pradesh, Uttarakhand, Sikkim, and Arunachal Pradesh. The estimated population is about 718 individuals. Ladakh has the highest number (~477). The snow leopard (Panthera uncia) is listed as "Vulnerable" on the IUCN Red List. The assessment used camera trapping and genetic analysis of scat samples across 13,000+ sq km of potential habitat.', source: 'Ministry of Environment, Forest and Climate Change / Wildlife Institute of India', difficulty: 'hard' },
  { slug: 'env-india-asiatic-lion-gir-census-2020', categoryId: 'cat-environment', text: 'According to the 2020 census, approximately how many Asiatic lions live in the Gir forest and surrounding areas?', options: ['About 400', 'About 523', 'About 674', 'About 1,000'], correctIndex: 2, explanation: 'The 2020 Asiatic Lion Census (the 15th, conducted by the Gujarat Forest Department) counted 674 Asiatic lions in the Gir forest and surrounding areas of Gujarat — an increase from 523 in 2015. The lions are found in Gir National Park, Gir Wildlife Sanctuary, Pania Sanctuary, and surrounding villages in Junagadh, Gir Somnath, Amreli, and Bhavnagar districts. The Asiatic lion is listed as "Endangered" on the IUCN Red List.', source: 'Gujarat Forest Department / IUCN Red List / Ministry of Environment', difficulty: 'medium' },
  { slug: 'env-india-ganges-dolphin-count-2023', categoryId: 'cat-environment', text: 'According to a 2023 survey by the NMCG and WII, the Gangetic dolphin population in the Ganga river basin is approximately how many?', options: ['About 1,000', 'About 2,000', 'About 4,000+', 'About 10,000'], correctIndex: 2, explanation: 'According to the NMCG (National Mission for Clean Ganga) and Wildlife Institute of India (WII) survey (2023), the Gangetic dolphin population in the Ganga river basin is approximately 4,000+ — an increase from about 2,000 in 2015. The Gangetic dolphin (Platanista gangetica) is India\'s national aquatic animal and is listed as "Endangered" on the IUCN Red List. The increase is attributed to improved water quality and flow under the Namami Gange programme.', source: 'National Mission for Clean Ganga (NMCG) / Wildlife Institute of India / IUCN Red List', difficulty: 'hard' },
  { slug: 'env-india-solar-park-bhadla-capacity', categoryId: 'cat-environment', text: 'The Bhadla Solar Park, one of the world\'s largest, is in which state and has what installed capacity?', options: ['Karnataka, 2,000 MW', 'Rajasthan, 2,245 MW', 'Gujarat, 1,500 MW', 'Andhra Pradesh, 1,000 MW'], correctIndex: 1, explanation: 'The Bhadla Solar Park in Jodhpur district, Rajasthan, has an installed capacity of 2,245 MW — making it one of the world\'s largest solar parks. It covers about 14,000 acres in the Thar Desert. It was developed by RRECL (Rajasthan Renewable Energy Corporation Ltd). India\'s total installed solar capacity is approximately 73 GW (as of mid-2024), targeting 500 GW non-fossil capacity by 2030.', source: 'Ministry of New and Renewable Energy (MNRE) / RRECL Rajasthan', difficulty: 'medium' },
  { slug: 'env-india-wildlife-corridor-elephant', categoryId: 'cat-environment', text: 'India\'s first elephant corridor was established in which state?', options: ['Karnataka', 'Kerala', 'Assam', 'Tamil Nadu'], correctIndex: 0, explanation: 'India\'s first officially notified elephant corridor was in Karnataka. India has 101 identified elephant corridors across 11 elephant-range states (as of the 2023 Elephant Corridor report by WTI and IUCN). These corridors allow elephants to move between fragmented habitats. About 70% of corridors are threatened by human activities. The corridors are notified by state forest departments under the Wild Life (Protection) Act, 1972.', source: 'Ministry of Environment, Forest and Climate Change / Wildlife Trust of India (WTI)', difficulty: 'hard' },
  { slug: 'env-india-clean-air-ncap-target', categoryId: 'cat-environment', text: 'The National Clean Air Programme (NCAP), launched in 2019, targets what reduction in PM2.5 and PM10 levels by 2024-26 (baseline 2017)?', options: ['10% reduction', '20-30% reduction', '50% reduction', '100% elimination'], correctIndex: 1, explanation: 'The NCAP, launched in January 2019, targets a 20-30% reduction in PM2.5 and PM10 levels by 2024 (later extended to 2026) using 2017 as the baseline. It covers 131 non-attainment cities (initially 102, expanded in 2022). The programme includes city-specific action plans, air quality monitoring networks, source apportionment studies, and biomass management. India\'s AQI (Air Quality Index) has 6 categories from "Good" (0-50) to "Severe+" (401-500).', source: 'Ministry of Environment, Forest and Climate Change / CPCB', difficulty: 'medium' },
  { slug: 'env-india-mangrove-loss-threats', categoryId: 'cat-environment', text: 'India\'s mangroves face the greatest threat from which human activity?', options: ['Tourism', 'Shrimp/prawn aquaculture (and coastal development)', 'Mining', 'Logging for timber'], correctIndex: 1, explanation: 'Shrimp/prawn aquaculture (shrimp farming) and coastal development are the greatest threats to India\'s mangroves. Large areas of mangrove forest have been cleared for shrimp farms, especially in West Bengal, Andhra Pradesh, and Odisha. Other threats include: urbanisation, port development, industrial pollution, and climate change (sea-level rise). India\'s mangrove cover is about 4,992 sq km (2021) and is being protected through Coastal Regulation Zone (CRZ) notifications and afforestation programmes.', source: 'Ministry of Environment, Forest and Climate Change / Forest Survey of India', difficulty: 'medium' },
  { slug: 'env-india-e-waste-rules-2022', categoryId: 'cat-environment', text: 'India is the world\'s third-largest e-waste generator. The E-Waste Management Rules were first notified in which year (later amended)?', options: ['2008', '2011', '2016', '2022'], correctIndex: 2, explanation: 'The E-Waste (Management) Rules were first notified in 2016 (replacing the 2011 rules), amended in 2018 and 2022. India generates about 3.2 million tonnes of e-waste annually (3rd largest globally, after China and USA). Only about 20-25% is formally recycled. The rules mandate Extended Producer Responsibility (EPR) — manufacturers must ensure collection and recycling of e-waste. The 2022 amendment added more items and strengthened EPR targets.', source: 'Ministry of Environment, Forest and Climate Change / CPCB / Central Pollution Control Board', difficulty: 'medium' },
  { slug: 'env-india-lion-tiger-reintroduction', categoryId: 'cat-environment', text: 'The "Project Lion" announced in 2020 aims to do what for Asiatic lions?', options: ['Breed lions in captivity', 'Establish lion populations beyond Gir (in other potential habitats)', 'Import lions from Africa', 'Create a gene bank only'], correctIndex: 1, explanation: '"Project Lion," announced on 15 August 2020, aims to establish Asiatic lion populations beyond Gir Forest in other potential habitats in Gujarat. This would reduce the risk of disease outbreaks (all 674 lions live in one area). Potential reintroduction sites include Kuno-Palpur (Madhya Pradesh, already prepared for lions but used for cheetahs), Sitamata (Rajasthan), and other areas. The project is modelled on Project Tiger\'s success.', source: 'Ministry of Environment, Forest and Climate Change / Gujarat Forest Department', difficulty: 'hard' },

  // ═══ cat-art (10) ═══
  { slug: 'art-mughal-painting-jahangir-fav', categoryId: 'cat-art', text: 'Emperor Jahangir (r. 1605-1627) is known for his particular interest in which subject in Mughal painting?', options: ['Religious scenes', 'Naturalistic depictions of plants, animals, and birds (including the famous "Turkey Cock")', 'Battle scenes only', 'Architectural plans'], correctIndex: 1, explanation: 'Jahangir had a deep interest in naturalism and commissioned detailed paintings of plants, animals, and birds. His court artist Ustad Mansur (the "Wonder of the Age") painted many species, including the famous "Turkey Cock" (a turkey, then exotic to India), the "Dodo" (now extinct), and the "Himalayan Blue Throat." Jahangir also commissioned the "Tuzuk-i-Jahangiri" (his autobiography) with illustrations. His reign is considered the golden age of Mughal natural history painting.', source: 'National Museum, New Delhi / Victoria and Albert Museum, London', difficulty: 'hard' },
  { slug: 'art-tagore-bengal-renaissance', categoryId: 'cat-art', text: 'Rabindranath Tagore founded Visva-Bharati University in 1921 at which location?', options: ['Kolkata', 'Santiniketan (Bolpur, West Bengal)', 'Dhaka', 'Shantipur'], correctIndex: 1, explanation: 'Tagore founded Visva-Bharati University in 1921 at Santiniketan (Bolpur, Birbhum district, West Bengal). His father, Debendranath Tagore, had established an ashram there in 1863. Visva-Bharati means "where the world makes a home in a single nest" — reflecting Tagore\'s vision of cultural synthesis. It became a Central University in 1951. Tagore also founded Sriniketan (1922) for rural reconstruction nearby. Santiniketan was inscribed as a UNESCO World Heritage Site in 2023.', source: 'UNESCO World Heritage List / Visva-Bharati University', difficulty: 'medium' },
  { slug: 'art-tamil-sangam-literature-three-kingdoms', categoryId: 'cat-art', text: 'Sangam literature describes three Tamil kingdoms. Which of the following is the correct pairing?', options: ['Chera (Kerala), Chola (Tamil Nadu coast), Pandya (Madurai)', ['Magadha, Maurya, Gupta'], 'Pallava, Chalukya, Rashtrakuta', 'Satavahana, Kushana, Shak'], correctIndex: 0, explanation: 'Sangam literature describes three Tamil kingdoms: the Cheras (Kerala region, capital Vanchi), the Cholas (Tamil Nadu northern coast, capital Uraiyur), and the Pandyas (southern Tamil Nadu, capital Madurai). Sangam literature (c. 300 BCE - 300 CE) comprises about 2,381 poems by 473 poets, compiled in anthologies like Ettuthogai (Eight Collections) and Pattupattu (Ten Songs). The Tamil Sangams (literary assemblies) were held in Madurai.', source: 'Sahitya Akademi / Encyclopaedia Britannica / Indian Council of Historical Research', difficulty: 'medium' },
  { slug: 'art-indian-classical-music-tanpura-role', categoryId: 'cat-art', text: 'The tanpura (tambura) is a stringed instrument used in Indian classical music. What is its primary function?', options: ['Playing melodies', 'Providing a continuous drone (the "sruti" or fundamental pitch) for the performer', 'Percussion accompaniment', 'Playing rhythm'], correctIndex: 1, explanation: 'The tanpura\'s primary function is to provide a continuous drone (sruti) — the fundamental pitch around which the performance revolves. It has 4 or 5 strings tuned to specific notes (usually Pa, Sa, Sa, Sa — from low to high). The tanpura is not plucked melodically; instead, strings are gently plucked in succession to maintain the drone. The drone helps the performer (vocalist or instrumentalist) stay in pitch and creates the harmonic foundation of Indian classical music.', source: 'Sangeet Natak Akademi / ITC Sangeet Research Academy', difficulty: 'medium' },
  { slug: 'art-bharatanatyam-margam-structure', categoryId: 'cat-art', text: 'A traditional Bharatanatyam recital (margam) typically follows a specific sequence. Which is the correct order of the first 3 items?', options: ['Varnam, Alarippu, Jatiswaram', 'Alarippu, Jatiswaram, Shabdam', 'Pushpanjali, Varnam, Tillana', 'Shabdam, Varnam, Alarippu'], correctIndex: 1, explanation: 'A traditional Bharatanatyam recital (margam) follows this sequence: 1) Pushpanjali (opening prayer), 2) Alarippu (pure dance, flower-like opening), 3) Jatiswaram (pure dance with musical composition), 4) Shabdam (expressive dance with story), 5) Varnam (centerpiece — combination of pure dance and expression), 6) Padam (expressive, devotional/love songs), 7) Tillana (fast-paced pure dance), 8) Shlokam/Mangalam (closing prayer). The margam was codified by the Tanjore Quartet (19th century).', source: 'Sangeet Natak Akademi / Kalakshetra Foundation', difficulty: 'hard' },
  { slug: 'art-ravi-varma-oleographs-popular', categoryId: 'cat-art', text: 'Raja Ravi Varma established a press to mass-produce his paintings as oleographs (colour prints). Where was this press located?', options: ['Mumbai', 'Kolkata', 'Lonavala (near Mumbai)', 'Chennai'], correctIndex: 2, explanation: 'Raja Ravi Varma established the Ravi Varma Press in Lonavala (near Mumbai) in 1894 (later shifted to Mumbai). The press produced oleographs — colour prints of his paintings of Hindu gods, goddesses, and mythological scenes. These prints made art accessible to the common people and shaped the popular visual imagination of Hindu deities across India. The press was later managed by his brother Raja Raja Varma. Varma is credited with establishing the fusion of Indian themes with European academic painting techniques.', source: 'National Gallery of Modern Art / Kiran Nadar Museum of Art', difficulty: 'hard' },
  { slug: 'art-indian-cinema-satyajit-ray-awards', categoryId: 'cat-art', text: 'Satyajit Ray received an Honorary Academy Award (Oscar) in 1992. How many days before his death did he receive it?', options: ['1 month', 'About 24 days (on his deathbed in Kolkata)', '3 months', '6 months'], correctIndex: 1, explanation: 'Satyajit Ray received the Honorary Academy Award on 30 March 1992, approximately 24 days before his death on 23 April 1992. The award was delivered to him at his hospital bed in Kolkata (he was too ill to travel to Los Angeles). Audrey Hepburn presented the award. Ray had been nominated for an Oscar for "Shatranj ke Khilari" (The Chess Players, 1977) for Best Foreign Language Film but did not win. The Apu Trilogy (Pather Panchali, Aparajito, Apur Sansar) is his most celebrated work.', source: 'Academy of Motion Picture Arts and Sciences / National Film Archive of India', difficulty: 'hard' },
  { slug: 'art-rigveda-mandala-10-purusha', categoryId: 'cat-art', text: 'The "Purusha Sukta" hymn in the Rigveda (Mandala 10) is significant for describing what concept?', options: ['The origin of the four varnas (social classes)', 'The creation of the universe from the cosmic man (Purusha)', 'Both — the cosmic sacrifice of Purusha from which the four varnas emerged', 'The battle between gods and demons'], correctIndex: 2, explanation: 'The "Purusha Sukta" (Rigveda 10.90) describes the cosmic sacrifice of the Purusha (Cosmic Man) — from whose body the universe and the four varnas (social classes) emerged: Brahmins from the mouth, Kshatriyas from the arms, Vaishyas from the thighs, and Shudras from the feet. This hymn (composed c. 1500-1000 BCE) is one of the earliest textual references to the varna system. It is still recited in Hindu rituals today.', source: 'Sahitya Akademi / Encyclopaedia Britannica / Rigveda 10.90 (Purusha Sukta)', difficulty: 'hard' },
  { slug: 'art-kerala-kathakali-natyashastra', categoryId: 'cat-art', text: 'Kathakali\'s system of facial expressions and hand gestures is derived from which ancient text?', options: ['Natya Shastra (by Bharata Muni)', ['Abhinaya Darpana (by Nandikeshvara)'], 'Sangeet Ratnakara', 'Both Natya Shastra and Hastalakshana Deepika'], correctIndex: 3, explanation: 'Kathakali\'s system of expressions and gestures is derived from both the "Natya Shastra" (ancient treatise on performing arts, c. 200 BCE - 200 CE) and the "Hastalakshana Deepika" (a Kerala-specific text on hand gestures). Kathakali uses 24 basic mudras from the Hastalakshana Deepika and the navarasas (9 emotions) from the Natya Shastra. The Natya Shastra is the foundational text for all Indian classical dance forms.', source: 'Sangeet Natak Akademi / Kerala Kalamandalam', difficulty: 'hard' },
  { slug: 'art-indian-literature-gitanjali-nobel', categoryId: 'cat-art', text: 'When Rabindranath Tagore received the Nobel Prize in Literature in 1913, he was the first person from which region to receive a Nobel Prize?', options: ['India only', 'Asia (the first Asian Nobel laureate)', 'The British Empire', 'The non-English-speaking world'], correctIndex: 1, explanation: 'Tagore was the first Asian (and non-European) to receive a Nobel Prize. He received the Nobel Prize in Literature in 1913 for "Gitanjali" (Song Offerings). The Nobel Committee praised his "consummate skill, perfect form, and profound spiritual insight." Tagore was born in 1861 in Calcutta (Kolkata) and died in 1941. He was also the first non-European to receive any Nobel Prize. C.V. Raman was the second Asian Nobel laureate (Physics, 1930).', source: 'Nobel Prize Foundation / Visva-Bharati University', difficulty: 'easy' },

  // ═══ cat-edu (10) ═══
  { slug: 'edu-india-neet-replaced-exam', categoryId: 'cat-edu', text: 'Before NEET was made the sole medical entrance exam in 2016, AIIMS conducted its own separate entrance exam until which year?', options: ['2016', '2018', '2020', '2022'], correctIndex: 2, explanation: 'AIIMS conducted its own separate entrance exam for MBBS admissions until 2019 (last exam). From 2020, NEET (conducted by NTA) became the sole entrance exam for ALL medical colleges in India, including AIIMS and JIPMER. The "One Nation, One Exam" policy was implemented through the NEET amendment. NEET was first conducted in 2013, withdrawn, and then reintroduced in 2016. NEET 2024 had about 24 lakh (2.4 million) registered candidates.', source: 'National Testing Agency (NTA) / Ministry of Health / AIIMS', difficulty: 'medium' },
  { slug: 'edu-india-rte-act-no-detention', categoryId: 'cat-edu', text: 'The RTE Act, 2009 originally contained a "no-detention policy" (automatic promotion to the next class). This was amended in which year?', options: ['2015', '2017', '2019', '2022'], correctIndex: 2, explanation: 'The RTE Act, 2009 originally prohibited detention of students (automatic promotion from Class 1-8). The "no-detention policy" was controversial — critics argued it reduced learning accountability. The 2019 amendment to the RTE Act allowed states to conduct examinations at the end of Class 5 and Class 8, with the possibility of detention for students who fail. States can now choose their own detention policy.', source: 'Ministry of Education / RTE Amendment Act, 2019', difficulty: 'medium' },
  { slug: 'edu-india-iim-first-year', categoryId: 'cat-edu', text: 'The first IIM (Indian Institute of Management) was established in which year and in which city?', options: ['1958, Delhi', '1961, Calcutta (Kolkata)', '1962, Ahmedabad', '1973, Bangalore'], correctIndex: 1, explanation: 'IIM Calcutta was the first IIM, established in November 1961 (in collaboration with MIT Sloan, Government of West Bengal, and the Ford Foundation). IIM Ahmedabad was established in December 1961 (in collaboration with Harvard Business School). IIM Bangalore was established in 1973. As of 2024, there are 20 IIMs. The IIM Act, 2017 granted them "Institutions of National Importance" status, giving them more autonomy.', source: 'IIM Calcutta / Ministry of Education / IIM Council', difficulty: 'medium' },
  { slug: 'edu-india-aiims-institutes-count-2024', categoryId: 'cat-edu', text: 'As of 2024, approximately how many AIIMS (All India Institutes of Medical Sciences) have been sanctioned across India (including AIIMS New Delhi)?', options: ['About 10', 'About 15', 'About 22+', 'About 30'], correctIndex: 2, explanation: 'As of 2024, approximately 22+ AIIMS have been sanctioned under the Pradhan Mantri Swasthya Suraksha Yojana (PMSSY), in addition to AIIMS New Delhi (established 1956). These are at various stages of operationalisation. New AIIMS have been established in cities like Bhubaneswar, Jodhpur, Raipur, Rishikesh, Bhopal, Patna, and many others. The AIIMS Act was amended in 2012 to allow new AIIMS to be designated as "Institutions of National Importance."', source: 'Ministry of Health and Family Welfare / PMSSY', difficulty: 'medium' },
  { slug: 'edu-india-technical-education-aicte', categoryId: 'cat-edu', text: 'AICTE (All India Council for Technical Education) was established in which year as a statutory body?', options: ['1945', '1965', '1987', '1995'], correctIndex: 2, explanation: 'AICTE was established in 1945 as an advisory body and given statutory status in 1987 by the AICTE Act, 1986 (passed by Parliament). AICTE is the apex body for technical education in India (engineering, management, pharmacy, architecture, etc.). It grants approvals to technical institutions, sets norms and standards, and conducts the CMAT and GPAT exams. UGC oversees higher education (general/university-level), while AICTE oversees technical education.', source: 'AICTE / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-india-ugc-act-year', categoryId: 'cat-edu', text: 'The University Grants Commission (UGC) was established by an Act of Parliament in which year?', options: ['1947', '1953', '1956', '1962'], correctIndex: 2, explanation: 'The UGC was established in 1953 (informally) and given statutory status by the UGC Act, 1956. It is the apex body for higher education (universities and colleges) in India. UGC provides grants to universities, maintains standards, and coordinates higher education. It is being replaced by the Higher Education Commission of India (HECI) under the NEP 2020 (bill pending as of 2024). UGC also conducts NET (now conducted by NTA) for eligibility of Assistant Professors.', source: 'University Grants Commission (UGC) / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-india-education-expenditure-gdp', categoryId: 'cat-edu', text: 'India\'s education expenditure as a percentage of GDP (as of 2023-24) is approximately what?', options: ['About 2.5-3%', 'About 4-4.6%', 'About 6%', 'About 8%'], correctIndex: 1, explanation: 'India\'s education expenditure is approximately 4-4.6% of GDP (as of 2023-24 Budget estimates, including central + state spending). The National Education Policy (NEP 1986, reaffirmed by NEP 2020) set a target of 6% of GDP for education spending. India has never consistently achieved the 6% target. The Kothari Commission (1964-66) also recommended 6%. Education is on the Concurrent List (Entry 25), so both the Centre and States can legislate.', source: 'Ministry of Finance (Union Budget) / Economic Survey of India / Ministry of Education', difficulty: 'medium' },
  { slug: 'edu-india-national-literacy-day', categoryId: 'cat-edu', text: 'International Literacy Day is observed globally on which date?', options: ['8 September', '8 October', '8 November', '22 December'], correctIndex: 0, explanation: 'International Literacy Day is observed on 8 September each year, as declared by UNESCO in 1966. India observes it on the same date. The Saakshar Bharat programme (launched on 8 September 2009) aimed to achieve 80% literacy by the end of the 11th Five Year Plan. India\'s literacy rate (2011 Census) was 74.04% (male 82.14%, female 65.46%). The delayed 2021 Census is expected to show improvement.', source: 'UNESCO / Ministry of Education', difficulty: 'easy' },
  { slug: 'edu-india-school-enrolment-gross', categoryId: 'cat-edu', text: 'India\'s Gross Enrolment Ratio (GER) at the elementary level (Class 1-8) is approximately what (as of 2021-22)?', options: ['About 75%', 'About 88-90%', 'About 100% (near universal)', 'About 120% (includes over-age and under-age children)'], correctIndex: 3, explanation: 'India\'s GER at the elementary level (Class 1-8) is approximately 103% (2021-22, UDISE+ data), which means more children are enrolled than the official school-age population. This is because the GER includes over-age and under-age children who may have enrolled late or repeated grades. At the secondary level (Class 9-10), the GER drops to about 58%, and at higher education (18-23 age group), it is about 28.4%.', source: 'Ministry of Education / UDISE+ (Unified District Information System for Education Plus)', difficulty: 'medium' },
  { slug: 'edu-india-ncert-established-year', categoryId: 'cat-edu', text: 'NCERT (National Council of Educational Research and Training) was established on which date?', options: ['15 August 1947', '1 September 1961', '26 January 1962', '1 July 1965'], correctIndex: 1, explanation: 'NCERT was established on 1 September 1961 as an autonomous organisation under the Ministry of Education. It develops textbooks, conducts educational research, trains teachers, and develops the National Curriculum Framework (NCF). NCERT textbooks are used by CBSE schools, KVs, NVs, and many state boards. NCERT also publishes research journals and educational materials. It is headquartered in New Delhi and has regional institutes (RIEs) across India.', source: 'NCERT official website / Ministry of Education', difficulty: 'medium' },
];

async function main() {
  console.log('=== Batch 8 Import ===\n');
  const existing = await db.quizQuestion.findMany({ select: { id: true, text: true } });
  const existingTexts = existing.map((q) => q.text);
  const existingSlugs = new Set(existing.map((q) => q.id));
  console.log(`Existing: ${existing.length}, Batch: ${BATCH.length}\n`);

  let imported = 0, skipped = 0, rejected = 0, warned = 0;
  const rejections: Array<{ slug: string; errors: string[] }> = [];
  const warningsLog: Array<{ slug: string; warnings: string[] }> = [];

  for (const q of BATCH) {
    if (existingSlugs.has(q.slug)) { skipped++; continue; }
    const errors: string[] = [];
    const warnings: string[] = [];

    if (!q.text || q.text.trim().length < 10) errors.push('text too short');
    if (q.options.length !== 4) errors.push(`expected 4 options, got ${q.options.length}`);
    if (q.correctIndex < 0 || q.correctIndex >= 4) errors.push('invalid correctIndex');
    if (!q.explanation || q.explanation.trim().length < 10) errors.push('explanation too short');
    if (!q.source || q.source.trim().length < 3) errors.push('source required');
    if (!['easy','medium','hard'].includes(q.difficulty)) errors.push('invalid difficulty');

    const dupResult = checkDuplicate(q.text, existingTexts);
    if (dupResult.isExactDuplicate) errors.push(`exact duplicate: ${dupResult.reason}`);
    else if (dupResult.isNearDuplicate) warnings.push(`near-duplicate: ${dupResult.reason}`);

    if (errors.length > 0) { rejected++; rejections.push({ slug: q.slug, errors }); continue; }
    if (warnings.length > 0) { warned++; warningsLog.push({ slug: q.slug, warnings }); }

    const options = q.options.map((text, i) => ({ id: String.fromCharCode(97 + i), text }));
    try {
      await db.quizQuestion.create({
        data: {
          id: q.slug, categoryId: q.categoryId, text: q.text.trim(), translations: '{}',
          options: JSON.stringify(options), correctOptionIndex: q.correctIndex,
          explanation: q.explanation.trim(), explanationTranslations: '{}',
          source: q.source.trim(), difficulty: q.difficulty, language: 'en', published: true,
        },
      });
      existingTexts.push(q.text);
      imported++;
    } catch (e) {
      rejected++;
      rejections.push({ slug: q.slug, errors: [(e as Error).message] });
    }
  }

  console.log(`\n=== Import Summary ===`);
  console.log(`  Imported: ${imported}`);
  console.log(`  Skipped: ${skipped}`);
  console.log(`  Rejected: ${rejected}`);
  console.log(`  Warnings: ${warned}`);
  if (rejections.length > 0) {
    console.log(`\n  --- Rejected ---`);
    for (const r of rejections) console.log(`  [${r.slug}] ${r.errors.join('; ')}`);
  }
  if (warningsLog.length > 0) {
    console.log(`\n  --- Near-duplicate warnings ---`);
    for (const w of warningsLog) console.log(`  [${w.slug}] ${w.warnings.join('; ')}`);
  }

  console.log(`\n=== Post-import counts ===`);
  const allCats = ['cat-gk','cat-history','cat-geography','cat-civics','cat-science','cat-sports','cat-culture','cat-economy','cat-environment','cat-art','cat-edu'];
  let total = 0;
  for (const cat of allCats) {
    const c = await db.quizQuestion.count({ where: { categoryId: cat } });
    if (c > 0) console.log(`  ${cat}: ${c}`);
    total += c;
  }
  console.log(`  TOTAL: ${total}`);
}

main().then(() => process.exit(0));
